// neon.test.js — PARTIAL coverage (on purpose).
//
// What is covered today: the collision primitive and a couple of physics
// bounces. What is NOT covered yet: score and combo (see ISSUES.md #5), nor
// level progression. This is a starting point for the testing work ahead, not
// a complete suite.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  frame,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

const mockCtx = {
  fillRect: () => {},
  fillStyle: '',
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
};

test('brick bounce: top face hit flips vy', () => {
  const state = createState(1);
  const brick = { x: 100, y: 70, w: 72, h: 20, alive: true };
  state.bricks = [brick];
  // Ball coming from above, hitting the top face
  state.ball = { x: 136, y: 65, r: 7, vx: 0, vy: 300 }; // Need vy > 0 to hit top and bounce
  step(state, 0); // Trigger resolveBrickCollisions
  assert.ok(state.ball.vy < 0, 'vy should flip to UP');
});

test('brick bounce: bottom face hit flips vy', () => {
  const state = createState(1);
  const brick = { x: 100, y: 70, w: 72, h: 20, alive: true };
  state.bricks = [brick];
  // Ball coming from below, hitting the bottom face
  state.ball = { x: 136, y: 95, r: 7, vx: 0, vy: -300 }; // Need vy < 0 to hit bottom and bounce
  step(state, 0);
  assert.ok(state.ball.vy > 0, 'vy should flip to DOWN');
});

test('brick bounce: left face hit flips vx', () => {
  const state = createState(1);
  const brick = { x: 100, y: 70, w: 72, h: 20, alive: true };
  state.bricks = [brick];
  // Ball coming from left, hitting the left face
  state.ball = { x: 95, y: 80, r: 7, vx: 300, vy: 0 };
  step(state, 0);
  assert.ok(state.ball.vx < 0, 'vx should flip to LEFT');
});

test('brick bounce: right face hit flips vx', () => {
  const state = createState(1);
  const brick = { x: 100, y: 70, w: 72, h: 20, alive: true };
  state.bricks = [brick];
  // Ball coming from right, hitting the right face
  state.ball = { x: 175, y: 80, r: 7, vx: -300, vy: 0 };
  step(state, 0);
  assert.ok(state.ball.vx > 0, 'vx should flip to RIGHT');
});

test('brick bounce: corner hit flips both', () => {
  const state = createState(1);
  const brick = { x: 100, y: 70, w: 72, h: 20, alive: true };
  state.bricks = [brick];
  // Ball hitting the bottom-left corner: just a bit inside and moving diagonally
  state.ball = { x: 95, y: 95, r: 7, vx: 300, vy: 300 };
  step(state, 0);
  assert.ok(state.ball.vx < 0, 'vx should flip to LEFT');
  assert.ok(state.ball.vy < 0, 'vy should flip to UP');
});

test('brick bounce: prevent sticky bounce (push out)', () => {
  const state = createState(1);
  const brick = { x: 100, y: 70, w: 72, h: 20, alive: true };
  state.bricks = [brick];
  state.ball = { x: 136, y: 65, r: 7, vx: 0, vy: 300 };
  step(state, 0);
  assert.ok(!collides(state.ball, brick), 'ball should be pushed outside the brick');
});

test('brick bounce: no double flip on seams', () => {
  const state = createState(1);
  const brick1 = { x: 100, y: 70, w: 72, h: 20, alive: true };
  const brick2 = { x: 172, y: 70, w: 72, h: 20, alive: true };
  state.bricks = [brick1, brick2];
  // Ball hitting the seam between bricks
  state.ball = { x: 172, y: 80, r: 7, vx: 300, vy: 0 };
  step(state, 0);
  assert.ok(state.ball.vx < 0, 'vx should stay flipped to LEFT');
});

test('brick bounce: tunnelling detection (sweep)', () => {
  const state = createState(1);
  const brick = { x: 100, y: 70, w: 72, h: 20, alive: true };
  state.bricks = [brick];
  // Ball at Lvl 6 speed (~710px/s). In a 50ms frame, it moves 35.5px.
  // Jump over the brick from y=60 to y=95.5.
  state.ball = { x: 136, y: 60, r: 7, vx: 0, vy: 710 };
  const dt = 0.05;
  step(state, dt);
  // Ball is now at 60 + 710 * 0.05 = 95.5.
  // Brick is at y=70, h=20. (bottom=90).
  // Ball should have destroyed the brick.
  assert.equal(brick.alive, false, 'brick should be destroyed even if ball jumped over it');
});

function belowField() {
  return 500;
}

