test('brick bounce: corner hit flips both', () => {
  const state = createState(1);
  const brick = { x: 100, y: 70, w: 72, h: 20, alive: true };
  state.bricks = [brick];
  // Ball hitting the bottom-left corner: slightly inside on both axes
  // Ball at (96, 96), Brick at (100, 70, 72, 20). Ball r=7.
  // ball.x+r = 103 (> 100), ball.x-r = 89 (< 100) -> minX = 103-100 = 3
  // ball.y+r = 103 (> 70), ball.y-r = 89 (< 90) -> minY = 90-89 = 1
